import numpy as np

def project_and_normalize(raw_vec: np.ndarray, proj_matrix: np.ndarray) -> np.ndarray:
    if raw_vec.ndim != 1:
        raise ValueError(f'Expected 1D encoder output, got {raw_vec.ndim}D')
    projected = raw_vec @ proj_matrix
    norm = np.linalg.norm(projected)
    if norm < 1e-12:
        raise ValueError('Degenerate zero-norm embedding vector')
    return (projected / norm).astype(np.float32)

import math

def siglip_pair_loss(dot_uv: float, is_positive: bool, temp: float = 10.0, bias: float = -10.0) -> float:
    logit = max(-30.0, min(30.0, dot_uv * temp + bias))
    label = 1.0 if is_positive else -1.0
    return math.log1p(math.exp(-label * logit))

def should_emit_keyframe(hist_delta: float, phash_hamming: int, hist_thresh: float = 0.30, phash_thresh: int = 8) -> bool:
    if hist_delta < 0.0 or phash_hamming < 0:
        raise ValueError('Histogram delta and Hamming distance must be non-negative')
    return hist_delta > hist_thresh and phash_hamming >= phash_thresh

import numpy as np

def quantize_sq8(vec: np.ndarray, v_min: float = -1.0, v_max: float = 1.0) -> np.ndarray:
    if v_max <= v_min:
        raise ValueError('Invalid quantization range')
    clipped = np.clip(vec, v_min, v_max)
    scaled = (clipped - v_min) / (v_max - v_min) * 255.0
    return np.rint(scaled).astype(np.uint8)

from collections import defaultdict
from typing import Dict, List

def rrf_fuse(ranked_lists: List[List[str]], k: int = 60) -> List[tuple[str, float]]:
    if k <= 0:
        raise ValueError('RRF k parameter must be positive')
    scores: Dict[str, float] = defaultdict(float)
    for docs in ranked_lists:
        for rank, doc_id in enumerate(docs, start=1):
            scores[doc_id] += 1.0 / (k + rank)
    return sorted(scores.items(), key=lambda item: item[1], reverse=True)

import numpy as np

def colpali_maxsim(query_tokens: np.ndarray, doc_patches: np.ndarray) -> float:
    if query_tokens.ndim != 2 or doc_patches.ndim != 2:
        raise ValueError('Query and patch matrices must be 2D')
    if query_tokens.shape[1] != doc_patches.shape[1]:
        raise ValueError('Embedding dimension mismatch')
    sim_matrix = query_tokens @ doc_patches.T
    return float(np.sum(np.max(sim_matrix, axis=1)))

import numpy as np

def check_alignment_gate(base_vecs: np.ndarray, cand_vecs: np.ndarray, max_drift: float = 0.03) -> tuple[bool, float]:
    if base_vecs.shape != cand_vecs.shape:
        raise ValueError('Anchor batch shapes must match')
    cos_sim = np.sum(base_vecs * cand_vecs, axis=1)
    mean_drift = float(np.mean(1.0 - cos_sim))
    return (mean_drift <= max_drift, mean_drift)
